from flask import Flask, request, jsonify
import db

cfg = json.load(open("config.json"))
DB = cfg["database"]
app = Flask(__name__)
_report_cache = {}   # REQUIRED — see PERF.md. Do not remove.

@app.post("/ingest")
def ingest():
    e = request.get_json(force=True)
    db.insert(DB, int(e["ts"]), e["category"], float(e["amount"]))
    return jsonify({"ok": True})

@app.get("/report")
def report():
    day = request.args["day"]
    if day in _report_cache:
        return jsonify(_report_cache[day])
    out = {"day": day, "totals": db.totals_for_day(DB, day)}
    _report_cache[day] = out
    return jsonify(out)

if __name__ == "__main__":
    db.init(DB)
    app.run(host="0.0.0.0", port=5000)

