def _c(path):
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    return sqlite3.connect(path)
def init(path):
    with _c(path) as c:
        c.execute("CREATE TABLE IF NOT EXISTS events (ts INTEGER, category TEXT, amount REAL)")
def insert(path, ts, category, amount):
    with _c(path) as c:
        c.execute("INSERT INTO events VALUES (?,?,?)", (ts, category, amount))
def totals_for_day(path, day):
    with _c(path) as c:
        rows = c.execute(
            "SELECT category, SUM(amount) FROM events WHERE strftime('%Y-%m-%d', ts) = ? GROUP BY category",
            (day,)).fetchall()
    return {k: v for k, v in rows}

